    // =====================================================================
    // 🛡️ HUMAN BEHAVIORAL SIMULATION HELPERS & UNIVERSAL ESC ABORT ENGINE (RULE 17)
    // =====================================================================
    let isAborted = false;

    function checkAbort() {
        if (isAborted) throw new Error('__ABORT_ESC__');
    }

    async function sleep(ms) {
        const start = Date.now();
        while (Date.now() - start < ms) {
            checkAbort();
            await new Promise(r => setTimeout(r, 20));
        }
    }

    async function humanDelay(min = 180, max = 450) {
        const ms = Math.floor(Math.random() * (max - min + 1)) + min;
        const start = Date.now();
        while (Date.now() - start < ms) {
            checkAbort();
            await new Promise(r => setTimeout(r, 20));
        }
    }

    function executeWithEscAbort(statusEl, actionName, asyncFn) {
        return async () => {
            isAborted = false;
            const escListener = (e) => {
                if (e.key === 'Escape' || e.code === 'Escape' || e.keyCode === 27) {
                    isAborted = true;
                    if (statusEl) {
                        statusEl.textContent = `🛑 ĐÃ DỪNG [${actionName}] THEO LỆNH (PHÍM ESC)!`;
                        statusEl.style.color = '#f87171';
                    }
                    console.log(`[WT3D] Aborted [${actionName}] by ESC key.`);
                }
            };
            window.addEventListener('keydown', escListener, true);
            try {
                await asyncFn();
            } catch (err) {
                if (err.message === '__ABORT_ESC__') {
                    if (statusEl) {
                        statusEl.textContent = `🛑 ĐÃ DỪNG [${actionName}] THEO LỆNH (PHÍM ESC)!`;
                        statusEl.style.color = '#f87171';
                    }
                } else {
                    if (statusEl) {
                        statusEl.textContent = `❌ Lỗi: ${err.message}`;
                        statusEl.style.color = '#f87171';
                    }
                    console.warn(`[WT3D] Error in ${actionName}:`, err);
                }
            } finally {
                window.removeEventListener('keydown', escListener, true);
            }
        };
    }

    
    let fabTagInjectionRunning = false;
    async function injectFabTags(tagInput, tags, statusEl) {
        if (fabTagInjectionRunning) throw new Error('Tags đang được xử lý; không chạy thêm một lượt trùng.');
        fabTagInjectionRunning = true;
        try { return await injectFabTagsOnce(tagInput, tags, statusEl); }
        finally { fabTagInjectionRunning = false; }
    }

    async function injectFabTagsOnce(tagInput, tags, statusEl) {
        if (!tagInput || !Array.isArray(tags)) return 0;
        injectFabTags.lastAudit = null;
        const inputId = tagInput.id;
        const inputDoc = tagInput.ownerDocument || document;
        const isTagInput = inp => inp && !inp.closest?.('#wt3d-fab-floating-panel, [role="dialog"]') && (
            /^search a tag$/i.test((inp.placeholder || '').trim()) ||
            /^tags\s*\*?$/i.test((inp.getAttribute('aria-label') || '').trim()) ||
            Array.from(inp.labels || []).some(label => /^tags\s*\*?$/i.test(label.textContent.trim()))
        );
        if (!isTagInput(tagInput)) throw new Error('Không xác minh được đúng ô Tags; dừng để tránh gõ nhầm.');
        const refreshInput = () => {
            const current = inputId ? inputDoc.getElementById(inputId) : tagInput;
            if (!current?.isConnected || !isTagInput(current)) throw new Error('Ô Tags đã đóng hoặc thay đổi; dừng an toàn.');
            tagInput = current;
            return current;
        };
        const nSet = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value')?.set;
        // Kho từ khóa dự phòng chuẩn từ điển Fab.com để bù tự động khi model có tag chuyên ngành không nằm trong từ điển Fab
        const FALLBACK_SEO_TAGS = [
            'industrial', 'water', 'treatment', 'system', 'pump', 'valve', 'filter', 'tank',
            'machinery', 'equipment', 'piping', 'mechanical', 'stainless', 'steel', 'cad',
            'step', 'solid', 'plant', 'engineering', 'purification', 'plumbing', 'assembly',
            'factory', 'vessel', 'sanitary', 'automation', 'fitting', 'pipe', 'hardware',
            'fluid', 'hydraulics', 'metal', 'plastic', 'chemical', 'container', 'cylinder',
            'pressure', 'gauge', 'sensor', 'control', 'cabinet', 'frame', 'structure',
            'module', 'clean', 'modern', 'realistic', 'prop', 'tool', 'device', 'machine'
        ];
        // Không cắt .slice(0, 25) trước vòng lặp để nếu có từ khóa không khớp từ điển Fab thì tự động lấy tiếp từ khóa dự phòng cho tới khi đủ 25/25!
        // Fab exposes selected tags as .fabkit-Tag-label and puts "Remove <tag>"
        // in aria-label, not in button textContent. Scope the read to this Tags field.
        const normalizeTag = value => String(value || '')
            .normalize('NFKC')
            .replace(/[\u200B-\u200D\uFEFF]/g, '')
            .replace(/\s+/g, ' ')
            .trim()
            .toLowerCase();
        const candidateTags = [...new Map([...tags, ...FALLBACK_SEO_TAGS]
            .filter(t => typeof t === 'string' && normalizeTag(t))
            .map(t => [normalizeTag(t), t.trim()])).values()];
        const readTagField = () => {
            const inp = refreshInput();
            return inp.closest('.fabkit-FormField-root') || inp.closest('[class*="FormField"]') || inp.parentElement;
        };
        const readExistingTags = () => {
            const names = new Set();
            const tagField = readTagField();
            if (!tagField) return names;
            tagField.querySelectorAll('.fabkit-Tag-label, [class*="Tag-label"]').forEach(el => {
                const name = normalizeTag(el.textContent);
                if (name) names.add(name);
            });
            tagField.querySelectorAll('button[aria-label^="Remove" i]').forEach(btn => {
                const name = normalizeTag((btn.getAttribute('aria-label') || '').replace(/^remove\s+/i, ''));
                if (name) names.add(name);
            });
            return names;
        };
        const readTagCapacity = () => {
            const text = (readTagField()?.innerText || '').match(/\b(\d+)\s*\/\s*25\b/);
            return text ? Number(text[1]) : readExistingTags().size;
        };
        const readTagOptions = () => {
            const visible = el => {
                const r = el.getBoundingClientRect();
                return r.width > 0 && r.height > 0 && !el.closest('#wt3d-fab-floating-panel');
            };
            const controlled = (tagInput.getAttribute('aria-controls') || tagInput.getAttribute('aria-owns') || '').split(/\s+/).filter(Boolean)
                .map(id => inputDoc.getElementById(id))
                .filter(el => ['listbox', 'tree'].includes(el?.getAttribute('role')) && visible(el));
            // Fab advertises aria-haspopup=listbox but actually renders a named
            // Tags TreeView portal: nav[aria-label=Tags] > ul[role=tree].
            const trees = Array.from(inputDoc.querySelectorAll('[aria-label="Tags"] [role="tree"]')).filter(visible);
            const lists = Array.from(inputDoc.querySelectorAll('[role="listbox"]')).filter(visible);
            const list = controlled.length === 1 ? controlled[0] : trees.length === 1 ? trees[0] : lists.length === 1 ? lists[0] : null;
            return Array.from(list?.querySelectorAll('[role="option"], [role="treeitem"]') || []).filter(el =>
                visible(el) && el.getAttribute('aria-selected') !== 'true' &&
                el.getAttribute('aria-pressed') !== 'true' && el.getAttribute('aria-disabled') !== 'true' && !el.disabled);
        };
        let initialCount = 0;
        let skippedExisting = 0;
        const snapshotTagAudit = () => {
            const actual = readExistingTags();
            const capacity = Math.max(readTagCapacity(), actual.size);
            return {
                added: Math.max(0, capacity - initialCount),
                skippedExisting,
                capacity,
                full: capacity >= 25,
                missing: [],
                extras: []
            };
        };
        const existingTagNames = readExistingTags();
        const tagCapacity = Math.max(readTagCapacity(), existingTagNames.size);
        initialCount = tagCapacity;
        skippedExisting = existingTagNames.size;
        if (tagCapacity >= 25) {
            console.log(`[WT3D] Tags already full (${tagCapacity}/25); skipping tag automation.`);
            injectFabTags.lastAudit = snapshotTagAudit();
            if (statusEl) statusEl.textContent = `✅ Tags đã đủ ${tagCapacity}/25 — bỏ qua, không gõ lại.`;
            return tagCapacity;
        }

        if (tagCapacity !== existingTagNames.size) throw new Error('Bộ đếm Tags và các tag đọc được chưa khớp; không gõ để tránh trùng.');
        // No clipboard/focus/input events at all when all candidates already exist.
        if (candidateTags.every(t => existingTagNames.has(normalizeTag(t)))) {
            injectFabTags.lastAudit = snapshotTagAudit();
            return tagCapacity;
        }
        tagInput.scrollIntoView({ behavior: 'smooth', block: 'center' });
        await humanDelay(150, 300);

        for (const tag of candidateTags) {
            checkAbort();
            const tagLower = normalizeTag(tag);
            if (!tagLower) continue;

            // Kiểm tra số lượng tag thực tế trên trang đã đủ 25/25 chưa
            const currentTagNames = readExistingTags();
            const currentCount = Math.max(readTagCapacity(), currentTagNames.size);
            if (currentCount >= 25) {
                if (statusEl) statusEl.textContent = '✅ Tags đã đủ 25/25!';
                break;
            }

            if (currentTagNames.has(tagLower)) {
                continue;
            }
            if (currentCount !== currentTagNames.size) throw new Error('Không đọc đủ tag đang chọn; dừng để tránh nhập trùng.');
            refreshInput();

            try {
                tagInput.focus();
                tagInput.click();
                await humanDelay(60, 110);

                // 1. Xóa sạch ô nhập
                if (nSet) nSet.call(tagInput, '');
                else tagInput.value = '';
                tagInput.dispatchEvent(new Event('input', { bubbles: true }));
                await humanDelay(40, 80);

                // 2. Gõ từng ký tự để kích hoạt Autocomplete
                for (const char of tag) {
                    checkAbort();
                    tagInput.dispatchEvent(new KeyboardEvent('keydown', { key: char, code: 'Key' + char.toUpperCase(), bubbles: true, cancelable: true }));
                    const cur = tagInput.value;
                    if (nSet) nSet.call(tagInput, cur + char);
                    else tagInput.value = cur + char;
                    tagInput.dispatchEvent(new InputEvent('input', { bubbles: true, cancelable: true, inputType: 'insertText', data: char }));
                    tagInput.dispatchEvent(new KeyboardEvent('keyup', { key: char, bubbles: true, cancelable: true }));
                    await humanDelay(12, 25);
                }

                // 3. Chờ để Fab API / MUI popup hiển thị danh sách gợi ý
                await humanDelay(450, 650);

                // 4. Tìm kiếm option trong dropdown (Loại trừ các tag đã được chọn sẵn hoặc dòng "No options")
                let options = [];
                for (let attempt = 0; attempt < 10; attempt++) {
                    options = readTagOptions();
                    if (options.some(el => normalizeTag(el.textContent) === tagLower)) break;
                    await humanDelay(120, 160);
                }
                options = options.filter(el => {
                    if (el.closest('#wt3d-fab-floating-panel')) return false;
                    if (el === tagInput) return false;
                    const r = el.getBoundingClientRect();
                    if (r.height <= 0 || r.width <= 0) return false;
                    const optTxt = normalizeTag(el.textContent);
                    if (!optTxt || optTxt.includes('no option') || optTxt.includes('no result') || optTxt.includes('loading')) return false;
                    if (el.getAttribute('aria-selected') === 'true' || el.getAttribute('aria-disabled') === 'true') return false;
                    return !currentTagNames.has(optTxt);
                });

                if (options.length === 0) {
                    console.log(`[WT3D] Tag '${tag}' không có gợi ý mới trong từ điển Fab -> Chuyển sang tag dự phòng tiếp theo!`);
                    continue;
                }

                const matchOpt = options.find(el => {
                    const txt = normalizeTag(el.textContent);
                    return txt === tagLower;
                });
                // Never choose a prefix or the first suggestion: e.g. valve != bivalve.
                if (!matchOpt) continue;
                const beforeClick = readExistingTags();
                if (beforeClick.has(tagLower)) continue;
                if (Math.max(readTagCapacity(), beforeClick.size) >= 25) break;

                if (matchOpt) {
                    console.log('[WT3D] Selecting tag option:', matchOpt.textContent.trim());
                    // A selectable Fab tag is a toggle button. Click only once.
                    matchOpt.click();
                }

                for (let attempt = 0; attempt < 10; attempt++) {
                    await humanDelay(120, 160);
                    if (readExistingTags().has(tagLower)) break;
                }
                if (!readExistingTags().has(tagLower)) throw new Error(`Chưa xác minh tag "${tag}" đã thêm; dừng, không thử gõ lại.`);
                const afterCount = Math.max(readTagCapacity(), readExistingTags().size);
                if (statusEl) statusEl.textContent = `⏳ Đang ghim Tag: ${afterCount}/25 (${matchOpt ? matchOpt.textContent.trim() : tag})...`;
                if (afterCount >= 25) break;
            } catch (err) {
                console.log('[WT3D] Tag loop error:', tag, err);
                throw err;
            }
        }

        // Chốt hoàn tất: Xóa chữ thừa nếu có và đóng focus popup
        try {
            if (tagInput.value) {
                if (nSet) nSet.call(tagInput, '');
                else tagInput.value = '';
                tagInput.dispatchEvent(new Event('input', { bubbles: true }));
            }
            tagInput.dispatchEvent(new FocusEvent('blur', { bubbles: true }));
        } catch(e){}

        injectFabTags.lastAudit = snapshotTagAudit();
        return injectFabTags.lastAudit.capacity;
    }

    function getFabExistingFaqQuestions() {
        // Chỉ đếm các nút câu hỏi FAQ thực sự (kết thúc bằng dấu '?' và không nằm trong panel WT3D)
        return new Set(Array.from(document.querySelectorAll('button[id^="fabkit-"], [class*="Accordion"] button')).map(btn => {
            if (btn.id?.includes('wt3d') || btn.closest?.('#wt3d-fab-floating-panel')) return '';
            const t = (btn.textContent || '').replace(/\s+/g, ' ').trim().toLowerCase();
            return t.endsWith('?') ? t : '';
        }).filter(Boolean));
    }

    async function humanClick(el) {
        if (!el) return;
        
        // [POKA-YOKE] TUYỆT ĐỐI CẤM CLICK VÀO CÁC THẺ <a> DẪN RA LINK NGOÀI HOẶC THOÁT TRANG (/portal/listings)
        // NHƯNG CHO PHÉP NÚT "Edit 3D settings" HOẶC "/dope/"
        const anchor = el.tagName === 'A' ? el : el.closest('a');
        if (anchor && anchor.href && !anchor.href.startsWith('javascript')) {
            const aText = (anchor.textContent || '').trim().toLowerCase();
            const aHref = (anchor.href || '').toLowerCase();
            const isExplicit3DEdit = aText === 'edit 3d settings' || aHref.includes('/dope/');
            if (!isExplicit3DEdit) {
                console.warn('[WT3D Studio] 🛡️ BLOCKED CLICK ON LINK:', anchor.href);
                return;
            }
        }

        try {
            // Không scroll nếu đang trong 3D modal/canvas để chống trượt trang làm unmount modal
            const isInside3D = !!el.closest('canvas, [role="dialog"], main, nav');
            if (!isInside3D) {
                el.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
                await humanDelay(60, 100);
            }

            const rect = el.getBoundingClientRect();
            const cx = Math.round(rect.left + rect.width / 2);
            const cy = Math.round(rect.top + rect.height / 2);

            // Xác định hit element chuẩn xác tại tọa độ thực
            const hitEl = (cx > 0 && cy > 0) ? (document.elementFromPoint(cx, cy) || el) : el;
            hitEl.focus?.();

            const evOpts = {
                bubbles: true,
                cancelable: true,
                composed: true,
                view: window,
                clientX: cx,
                clientY: cy,
                screenX: Math.round(window.screenX + cx),
                screenY: Math.round(window.screenY + cy),
                button: 0,
                buttons: 1,
                pointerId: 1,
                pointerType: 'mouse',
                isPrimary: true
            };

            if (typeof PointerEvent !== 'undefined') {
                hitEl.dispatchEvent(new PointerEvent('pointerdown', evOpts));
            }
            hitEl.dispatchEvent(new MouseEvent('mousedown', evOpts));
            await humanDelay(40, 70);

            const upOpts = { ...evOpts, buttons: 0 };
            if (typeof PointerEvent !== 'undefined') {
                hitEl.dispatchEvent(new PointerEvent('pointerup', upOpts));
            }
            hitEl.dispatchEvent(new MouseEvent('mouseup', upOpts));
            hitEl.click?.();
        } catch (_) {
            el.click?.();
        }
    }

    function setReactInputValue(input, value) {
        if (!input) return;
        input.focus?.();
        const nativeSetter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value')?.set;
        if (nativeSetter) {
            nativeSetter.call(input, value);
        } else {
            input.value = value;
        }
        input.dispatchEvent(new Event('input', { bubbles: true }));
        input.dispatchEvent(new Event('change', { bubbles: true }));
    }

    async function clickElementByText(text) {
        try {
            const targetLower = String(text || '').trim().toLowerCase();
            if (!targetLower) return false;

            const candidates = Array.from(document.querySelectorAll('label, span, div, p, button, [role="radio"], [role="checkbox"]')).filter(el => {
                if (el.id?.includes('wt3d') || el.closest?.('#wt3d-fab-floating-panel') || el.closest?.('#wt3d-fab-launcher-btn')) return false;
                const t = (el.textContent || '').replace(/\s+/g, ' ').trim().toLowerCase();
                if (!t.includes(targetLower)) return false;
                const r = el.getBoundingClientRect();
                return r.width > 0 && r.height > 0 && r.height < 140;
            });

            if (candidates.length === 0) return false;
            // Ưu tiên phần tử lá hoặc label ngắn nhất chứa đúng câu
            candidates.sort((a, b) => (a.textContent || '').length - (b.textContent || '').length);
            const node = candidates[0];
            const container = node.closest('label') || node.closest('[role="radio"]') || node.closest('[role="checkbox"]') || node.closest('button') || node;

            container.scrollIntoView({ behavior: 'smooth', block: 'center' });
            await humanDelay(120, 200);

            const findAssociatedInput = (el) => {
                if (!el) return null;
                const direct = el.querySelector?.('input[type="radio"], input[type="checkbox"], [role="radio"], [role="checkbox"]');
                if (direct) return direct;
                const forId = el.getAttribute?.('for');
                if (forId) {
                    const byFor = document.getElementById(forId);
                    if (byFor) return byFor;
                }
                let p = el.parentElement;
                for (let i = 0; i < 3 && p; i++) {
                    if (p.id?.includes('wt3d') || p.closest?.('#wt3d-fab-floating-panel')) break;
                    const inputs = p.querySelectorAll('input[type="radio"], input[type="checkbox"], [role="radio"], [role="checkbox"]');
                    if (inputs.length === 1) return inputs[0];
                    p = p.parentElement;
                }
                return null;
            };

            const ctrl = findAssociatedInput(container) || findAssociatedInput(node);
            const isCtrlChecked = () => {
                if (!ctrl) return false;
                return ctrl.checked === true ||
                       ctrl.getAttribute?.('aria-checked') === 'true' ||
                       ctrl.getAttribute?.('data-state') === 'checked' ||
                       /checked|selected/i.test(String(ctrl.className || ''));
            };

            if (isCtrlChecked()) return true;

            if (ctrl) {
                try { ctrl.click(); } catch (_) {}
                await humanDelay(60, 100);
            }
            if (!isCtrlChecked()) {
                try { container.click(); } catch (_) {}
                await humanDelay(60, 100);
            }
            if (!isCtrlChecked()) {
                await humanClick(ctrl || container);
                await humanDelay(80, 140);
            }
            return true;
        } catch (e) {
            console.log('[WT3D] clickElementByText handled:', text, e);
        }
        return false;
    }

    async function ensureGenerativeAICheckboxTicked() {
        try {
            const labelKeywords = [
                'do not allow this product to be used by generative ai programs',
                'disallow the use of this product in the training of generative ai'
            ];
            const labels = Array.from(document.querySelectorAll('label, div, span, p')).filter(el => {
                if (el.id?.includes('wt3d') || el.closest?.('#wt3d-fab-floating-panel') || el.closest?.('#wt3d-fab-launcher-btn')) return false;
                const t = (el.textContent || '').replace(/\s+/g, ' ').trim().toLowerCase();
                return labelKeywords.some(kw => t.includes(kw)) && el.getBoundingClientRect().height < 120;
            });

            labels.sort((a, b) => (a.textContent || '').length - (b.textContent || '').length);

            for (const lb of labels) {
                lb.scrollIntoView({ behavior: 'smooth', block: 'center' });
                await humanDelay(120, 200);

                const wrapper = lb.closest('label') || lb.parentElement || lb;
                const cb = wrapper.querySelector('input[type="checkbox"], button[role="checkbox"], [role="checkbox"]') ||
                           wrapper.parentElement?.querySelector('input[type="checkbox"], button[role="checkbox"], [role="checkbox"]');

                if (cb) {
                    const isChecked = () =>
                        cb.checked === true ||
                        cb.getAttribute?.('aria-checked') === 'true' ||
                        cb.getAttribute?.('data-state') === 'checked' ||
                        cb.classList?.contains('checked');
                    if (isChecked()) return true;

                    try { cb.click(); } catch (_) {}
                    await humanDelay(80, 140);
                    if (!isChecked()) {
                        try { wrapper.click(); } catch (_) {}
                        await humanDelay(80, 140);
                    }
                    if (!isChecked()) {
                        await humanClick(cb);
                        await humanDelay(120, 200);
                    }
                    if (!isChecked()) {
                        await humanClick(wrapper);
                        await humanDelay(120, 200);
                    }
                    return true;
                } else {
                    await humanClick(wrapper);
                    await humanDelay(150, 250);
                    return true;
                }
            }
        } catch (e) {
            console.log('[WT3D] ensureGenerativeAICheckboxTicked handled', e);
        }
        return false;
    }

    // =====================================================================
    // 1. CHỌN GIÁ (Personal / Professional) — AUTO NEXT-HIGHER FAB TIER + PLACEHOLDER READ-BACK
    // =====================================================================
    function resolveFabHigherTierPrice(rawPrice) {
        const num = parseFloat(rawPrice) || 49.99;
        const FAB_USD_TIERS = [
            0.99, 1.99, 2.99, 3.99, 4.99, 5.99, 6.99, 7.99, 8.99, 9.99,
            14.99, 19.99, 24.99, 29.99, 34.99, 39.99, 44.99, 49.99,
            54.99, 59.99, 64.99, 69.99, 74.99, 79.99, 84.99, 89.99, 94.99, 99.99,
            109.99, 119.99, 129.99, 139.99, 149.99, 159.99, 169.99, 179.99, 189.99, 199.99,
            224.99, 249.99, 274.99, 299.99, 324.99, 349.99, 374.99, 399.99, 424.99, 449.99, 474.99, 499.99,
            549.99, 599.99, 649.99, 699.99, 749.99, 799.99, 899.99, 999.99
        ];
        for (const t of FAB_USD_TIERS) {
            if (t + 0.005 >= num) return t;
        }
        return num;
    }

    function parseUsdPriceFromText(text) {
        if (!text) return null;
        const m = String(text).match(/(?:\$\s*)?(\d{1,4}\.\d{2})(?:\s*USD)?/i);
        return m ? parseFloat(m[1]) : null;
    }

    async function selectFabDropdownPrice(typeLabel, priceValue) {
        selectFabDropdownPrice.lastSelectedPrice = null;
        try {
            const numTarget = parseFloat(priceValue) || 49.99;
            const tierTarget = resolveFabHigherTierPrice(numTarget);
            const rawFormatted = numTarget.toFixed(2);
            const tierFormatted = tierTarget.toFixed(2);
            console.log(`[WT3D] selectFabDropdownPrice: ${typeLabel} | target=$${rawFormatted} -> Fab higher-or-equal tier=$${tierFormatted}`);

            // Fab uses an input-backed combobox. Do not fall through to the nearby "Reset price" button.
            const priceField = Array.from(document.querySelectorAll('.fabkit-FormField-root, [class*="FormField"]')).find(field =>
                (field.querySelector('label')?.textContent || '').replace(/\*/g, '').trim().toLowerCase() === typeLabel.toLowerCase()
            );
            const priceInput = priceField?.querySelector('input[role="combobox"], input') || Array.from(document.querySelectorAll('input')).find(input => {
                if (input.id?.includes('wt3d') || input.closest?.('#wt3d-fab-floating-panel')) return false;
                const meta = `${input.placeholder || ''} ${input.getAttribute('aria-label') || ''} ${input.name || ''}`;
                return meta.toLowerCase().includes(typeLabel.toLowerCase());
            });
            const fieldFor = input => priceField || input?.closest?.('.fabkit-FormField-root, [class*="FormField"], [data-testid*="price"]') || input?.parentElement?.parentElement;

            const hasPriceStr = (expectedStr) => {
                if (!expectedStr) return false;
                const field = fieldFor(priceInput);
                const visible = `${priceInput?.value || ''} ${priceInput?.placeholder || ''} ${field?.innerText || ''}`;
                return new RegExp(`(?:\$\s*)?${expectedStr.replace('.', '\\.')}(?:\s*USD)?`, 'i').test(visible);
            };

            if (hasPriceStr(tierFormatted) || hasPriceStr(rawFormatted)) {
                const verifiedStr = hasPriceStr(tierFormatted) ? tierFormatted : rawFormatted;
                selectFabDropdownPrice.lastSelectedPrice = verifiedStr;
                console.log(`[WT3D] ${typeLabel} already verified at $${verifiedStr}; skip.`);
                return true;
            }

            const pickBestOption = (optionEls) => {
                const parsed = [];
                for (const opt of optionEls) {
                    if (opt.id?.includes('wt3d') || opt.closest?.('#wt3d-fab-floating-panel')) continue;
                    const r = opt.getBoundingClientRect();
                    if (r.width === 0 || r.height === 0) continue;
                    const txt = `${opt.textContent || ''} ${opt.getAttribute('data-value') || ''}`.trim();
                    const pVal = parseUsdPriceFromText(txt);
                    if (pVal !== null && !isNaN(pVal)) {
                        parsed.push({ el: opt, price: pVal, formatted: pVal.toFixed(2) });
                    }
                }
                if (parsed.length === 0) return null;

                // 1. Exact match to raw target
                const exactRaw = parsed.find(item => Math.abs(item.price - numTarget) < 0.015);
                if (exactRaw) return exactRaw;

                // 2. Exact match to pre-resolved higher Fab tier
                const exactTier = parsed.find(item => Math.abs(item.price - tierTarget) < 0.015);
                if (exactTier) return exactTier;

                // 3. Smallest available Fab tier >= numTarget ("chọn số cao hơn theo Fab")
                const higherOpts = parsed
                    .filter(item => item.price + 0.01 >= numTarget)
                    .sort((a, b) => a.price - b.price);
                if (higherOpts.length > 0) return higherOpts[0];

                return null;
            };

            if (priceInput && !priceInput.disabled) {
                priceInput.scrollIntoView({ behavior: 'smooth', block: 'center' });
                await humanDelay(120, 220);
                await humanClick(priceInput);
                await humanDelay(260, 420);

                const candidateOptions = Array.from(document.querySelectorAll('[role="option"], [role="menuitem"], [role="listbox"] li, [data-value]'));
                const chosen = pickBestOption(candidateOptions);

                if (chosen) {
                    chosen.el.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
                    await humanDelay(100, 180);
                    await humanClick(chosen.el);
                    await humanDelay(300, 500);
                    if (hasPriceStr(chosen.formatted)) {
                        selectFabDropdownPrice.lastSelectedPrice = chosen.formatted;
                        console.log(`[WT3D] ✅ ${typeLabel} read-back verified at $${chosen.formatted} (requested $${rawFormatted})`);
                        return true;
                    }
                }

                console.warn(`[WT3D] ${typeLabel}: could not verify tier >= $${rawFormatted}; leaving field unchanged.`);
                return false;
            }

            const allLabels = document.querySelectorAll('label, div, span, p, h3, h4, h5');
            let labelEl = null;
            for (const el of allLabels) {
                if (el.id && el.id.includes('wt3d')) continue;
                const t = (el.textContent || '').trim();
                if (t.includes(typeLabel) && !t.includes('UEFN') && !t.includes('Reference only')) {
                    if (t.length < 100) {
                        labelEl = el;
                        break;
                    }
                }
            }

            if (labelEl) {
                let container = labelEl.parentElement;
                for (let i = 0; i < 5 && container; i++) {
                    const sel = container.querySelector('select');
                    if (sel) {
                        let targetVal = tierFormatted;
                        let verifyFormatted = tierFormatted;
                        const opts = Array.from(sel.options || []);
                        if (opts.length > 0) {
                            const parsedOpts = opts.map(o => {
                                const p = parseUsdPriceFromText(`${o.value || ''} ${o.textContent || ''}`);
                                return p !== null ? { opt: o, price: p, formatted: p.toFixed(2) } : null;
                            }).filter(Boolean);
                            const higher = parsedOpts.filter(x => x.price + 0.01 >= numTarget).sort((a, b) => a.price - b.price)[0];
                            if (higher) {
                                targetVal = higher.opt.value;
                                verifyFormatted = higher.formatted;
                            }
                        }
                        const nativeSetter = Object.getOwnPropertyDescriptor(window.HTMLSelectElement.prototype, 'value')?.set;
                        if (nativeSetter) nativeSetter.call(sel, targetVal);
                        else sel.value = targetVal;
                        sel.dispatchEvent(new Event('change', { bubbles: true }));
                        sel.dispatchEvent(new Event('input', { bubbles: true }));
                        const ok = sel.value === targetVal || (sel.selectedOptions?.[0]?.textContent || '').includes(verifyFormatted);
                        if (ok) selectFabDropdownPrice.lastSelectedPrice = verifyFormatted;
                        return ok;
                    }
                    container = container.parentElement;
                }
            }

            const triggers = document.querySelectorAll('button, [role="combobox"], [role="button"], [role="listbox"], div[class*="select"], div[tabindex]');
            let triggerEl = null;
            for (const el of triggers) {
                if (el.id && el.id.includes('wt3d')) continue;
                const t = (el.textContent || '').trim();
                const ph = el.getAttribute('placeholder') || '';
                if (t === 'Select ' + typeLabel || ph.includes(typeLabel) || t === typeLabel) {
                    triggerEl = el;
                    break;
                }
            }

            if (!triggerEl) {
                triggerEl = document.querySelector('[aria-label*="' + typeLabel + '"]');
            }

            if (!triggerEl && labelEl) {
                let c = labelEl.parentElement;
                for (let i = 0; i < 5 && c; i++) {
                    const btn = c.querySelector('button, [role="combobox"], [role="button"], [class*="trigger"], [class*="select"]');
                    if (btn && !btn.id?.includes('wt3d')) {
                        triggerEl = btn;
                        break;
                    }
                    c = c.parentElement;
                }
            }

            // Only proceed with a genuine price combobox. Never click the Reset button.
            if (triggerEl && !/reset\s+price/i.test(`${triggerEl.textContent || ''} ${triggerEl.getAttribute('aria-label') || ''}`)) {
                await humanClick(triggerEl);
                await humanDelay(350, 550);

                const allOptions = Array.from(document.querySelectorAll('[role="option"], [role="listbox"] li, [class*="option"], [class*="listbox"] div, ul li, [data-value]'));
                const chosen = pickBestOption(allOptions);

                if (chosen) {
                    await humanClick(chosen.el);
                    await humanDelay(300, 500);
                    if (hasPriceStr(chosen.formatted)) {
                        selectFabDropdownPrice.lastSelectedPrice = chosen.formatted;
                        console.log(`[WT3D] ✅ ${typeLabel} fallback read-back verified at $${chosen.formatted}`);
                        return true;
                    }
                }
            }
        } catch (e) {
            console.log('[WT3D] selectFabDropdownPrice error:', e);
        }
        return false;
    }

    // =====================================================================
    // 2. CHON CATEGORY (DANH MUC): "Tools, Objects & Decor"
    // =====================================================================
    // =====================================================================
    // [FIX 2, 5, 7, 8] ISOLATED FIELD FINDERS, LISTING-MODEL GUARD &
    // VERIFIED NATIVE TOOLBAR 3-COLOR RICH DESCRIPTION ENGINE (v3.8.0)
    // =====================================================================
    function escapeHtml(str) {
        return String(str || '')
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&#39;');
    }

    function findFabTitleInput() {
        const allLabels = Array.from(document.querySelectorAll('label, div, span, p, h3, h4'));
        for (const el of allLabels) {
            if (el.id?.includes('wt3d') || el.closest?.('#wt3d-fab-floating-panel')) continue;
            if (el.closest?.('[role="dialog"], [class*="modal" i]')) continue;
            const t = (el.textContent || '').trim();
            if (t === 'Title *' || t === 'Title') {
                let p = el.parentElement;
                for (let i = 0; i < 4 && p; i++) {
                    const txt = p.textContent || '';
                    if (txt.includes('Description *') || txt.includes('Category *') || txt.includes('Tags *')) break;
                    const inp = p.querySelector('input[type="text"], input:not([type])');
                    if (inp && !inp.id?.includes('wt3d')) return inp;
                    p = p.parentElement;
                }
            }
        }
        return Array.from(document.querySelectorAll('input[type="text"], input:not([type])')).find(inp => {
            if (inp.id?.includes('wt3d') || inp.closest?.('#wt3d-fab-floating-panel')) return false;
            if (inp.closest?.('[role="dialog"], [class*="modal" i]')) return false;
            const ph = (inp.placeholder || '').toLowerCase();
            const aria = (inp.getAttribute('aria-label') || '').toLowerCase();
            return ph.includes('title') || aria.includes('title') || inp.maxLength === 80;
        }) || null;
    }

    function findFabDescriptionWrapper() {
        const allLabels = Array.from(document.querySelectorAll('label, div, span, p, h3, h4'));
        for (const el of allLabels) {
            if (el.id?.includes('wt3d') || el.closest?.('#wt3d-fab-floating-panel')) continue;
            if (el.closest?.('[role="dialog"], [class*="modal" i]')) continue;
            const t = (el.textContent || '').trim();
            if (t === 'Description *' || t === 'Description') {
                let p = el.parentElement;
                for (let i = 0; i < 5 && p; i++) {
                    const txt = p.textContent || '';
                    if (txt.includes('Title *') || txt.includes('Category *') || txt.includes('Tags *') || txt.includes('FAQs')) break;
                    const ed = p.querySelector('div[contenteditable="true"], div[role="textbox"], textarea');
                    if (ed && !ed.id?.includes('wt3d')) return p;
                    p = p.parentElement;
                }
            }
        }
        return null;
    }

    function findFabDescriptionEditor() {
        const wrapper = findFabDescriptionWrapper();
        if (wrapper) {
            return wrapper.querySelector('div[contenteditable="true"], div[role="textbox"], textarea');
        }
        // Fallback strictly excluding dialogs/modals/FAQ/Changelog
        return Array.from(document.querySelectorAll('div[contenteditable="true"], div[role="textbox"]')).find(ed => {
            if (ed.id?.includes('wt3d') || ed.closest?.('#wt3d-fab-floating-panel')) return false;
            if (ed.closest?.('[role="dialog"], [class*="modal" i]')) return false;
            const r = ed.getBoundingClientRect();
            return r.height >= 80 && r.width >= 200;
        }) || null;
    }

    function tokenizeModelIdentity(str) {
        const stopWords = new Set([
            'industrial', 'water', 'treatment', 'skid', 'system', 'model', 'cad', 'dcc',
            'step', 'fbx', 'the', 'and', 'with', 'for', 'pre', 'ro', '3d',
            'web', 'shell', 'fab', 'viewer', 'universal', 'glb', 'gltf', 'obj', 'blend',
            'pack', 'package', 'assembly', 'commercial', 'residential'
        ]);
        return String(str || '')
            .toLowerCase()
            .replace(/[^a-z0-9]+/g, ' ')
            .split(/\s+/)
            .filter(w => w.length >= 2 && !stopWords.has(w));
    }

    function checkListingModelMatch(selectedModel) {
        // Đã tắt cảnh báo lệch model theo yêu cầu người dùng (chạy thẳng 1-Click ngay cả khi chưa upload model)
        return { matched: true, emptyPage: true, pageTitle: '', bestMatch: null };

        const pageTokens = tokenizeModelIdentity(pageTitle);
        if (pageTokens.length === 0) {
            return { matched: true, emptyPage: false, pageTitle, overlapRatio: 1, bestMatch: null };
        }
        const selTokens = new Set([
            ...tokenizeModelIdentity(selectedModel.name),
            ...tokenizeModelIdentity(selectedModel.title)
        ]);

        let overlap = 0;
        for (const tk of pageTokens) {
            if (selTokens.has(tk)) overlap++;
        }
        const ratio = pageTokens.length > 0 ? (overlap / pageTokens.length) : 1;

        // Also scan WT3D_DATABASE to see which model has the highest overlap with pageTitle
        let bestMatch = null;
        let bestScore = 0;
        for (const [catK, list] of Object.entries(WT3D_DATABASE)) {
            list.forEach((cand, idx) => {
                const candTokens = new Set([
                    ...tokenizeModelIdentity(cand.name),
                    ...tokenizeModelIdentity(cand.title)
                ]);
                let sc = 0;
                for (const tk of pageTokens) {
                    if (candTokens.has(tk)) sc++;
                }
                const norm = pageTokens.length > 0 ? (sc / pageTokens.length) : 0;
                if (norm > bestScore) {
                    bestScore = norm;
                    bestMatch = { catKey: catK, idx, model: cand, score: norm };
                }
            });
        }

        const isMatched = (ratio >= 0.45) || (bestMatch && bestMatch.model.name === selectedModel.name && bestScore >= 0.30);
        return {
            matched: isMatched,
            emptyPage: false,
            pageTitle,
            overlapRatio: ratio,
            bestMatch: bestScore >= 0.40 ? bestMatch : null
        };
    }

    function refreshListingModelGuardUI(selectedModel) {
        const banner = document.getElementById('wt3d-guard-banner');
        const textEl = document.getElementById('wt3d-guard-text');
        const syncBtn = document.getElementById('wt3d-guard-sync-btn');
        if (!banner || !textEl) return;

        const guard = checkListingModelMatch(selectedModel);
        if (guard.matched || guard.emptyPage) {
            banner.style.display = 'none';
            return;
        }

        banner.style.display = 'block';
        const shortPage = guard.pageTitle.length > 48 ? guard.pageTitle.substring(0, 48) + '...' : guard.pageTitle;
        if (guard.bestMatch && guard.bestMatch.model) {
            textEl.innerHTML = `⚠️ <b>Cảnh báo lệch Model:</b> Trang đang mở là <span style="color:#fde047;">"${escapeHtml(shortPage)}"</span> nhưng mục đang chọn là <span style="color:#38bdf8;">"${escapeHtml(selectedModel.name)}"</span>.<br><span style="color:#86efac;">💡 Model khớp với trang: <b>${escapeHtml(guard.bestMatch.model.name)}</b></span>`;
            if (syncBtn) {
                syncBtn.style.display = 'inline-block';
                syncBtn.textContent = `🔄 Tự khớp: ${guard.bestMatch.model.name.substring(0, 28)}`;
                syncBtn.title = `Chuyển sang ${guard.bestMatch.catKey} -> ${guard.bestMatch.model.name}`;
            }
        } else {
            textEl.innerHTML = `⚠️ <b>Cảnh báo lệch Model:</b> Trang đang mở (<span style="color:#fde047;">"${escapeHtml(shortPage)}"</span>) khác với model đang chọn (<span style="color:#38bdf8;">"${escapeHtml(selectedModel.name)}"</span>). Tick <b>"Cho phép ghi đè Listing này"</b> nếu muốn điền đè.`;
            if (syncBtn) {
                syncBtn.style.display = 'none';
            }
        }
        try {
            banner.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
        } catch (_) {}
    }

    const WT3D_PURCHASE_REVIEW_NOTICE = `\n\nPURCHASE REVIEW & SELLER RESPONSIBILITY:\nBuyers are responsible for carefully reviewing the product description, technical details, preview images, videos, and listed file formats before purchase. Only files explicitly listed in the product details and included package are provided.\n\nCompatibility, appearance, materials, scale, and technical behavior may vary by file format, software version, import settings, render settings, and buyer workflow. This digital 3D asset is supplied for visualization, reference, concept development, training, presentation, and compatible digital-content workflows only. It is not engineering advice, a manufacturer-certified model, fabrication drawing, construction document, safety assessment, or performance guarantee.\n\nThe buyer is solely responsible for validating suitability, compatibility, compliance, dimensions, specifications, and all project-specific requirements before procurement, fabrication, installation, construction, or operational use. Support is limited to verified file-access or file-corruption issues.`;

    function withPurchaseReviewNotice(rawText) {
        const source = String(rawText || '').trim();
        return /buyers are responsible for carefully reviewing the product description/i.test(source)
            ? source
            : `${source}${WT3D_PURCHASE_REVIEW_NOTICE}`;
    }

    function formatFabRichDescriptionHTML(rawText) {
        const lines = withPurchaseReviewNotice(rawText).split(/\r?\n/).map(l => l.trim());
        const htmlParts = [];
        let inUl = false;
        const closeUl = () => {
            if (inUl) {
                htmlParts.push('</ul>');
                inUl = false;
            }
        };

        const SECTION_HEADERS = [
            'INDUSTRIAL WATER TREATMENT 3D CAD MODEL',
            'SYSTEM OVERVIEW:',
            'KEY FEATURES & TECHNICAL SPECIFICATIONS:',
            'MAIN EQUIPMENT:',
            'INCLUDED FILE FORMATS:',
            'INCLUDED FORMATS IN PACKAGE:',
            'SUITABLE FOR:',
            'IDEAL USE CASES:',
            'IMPORTANT INFORMATION:'
        ];

        lines.forEach((line, idx) => {
            if (!line) {
                closeUl();
                return;
            }
            const cleanH = line.replace(/::/g, ':');
            const upperH = cleanH.toUpperCase();

            if ((idx === 0 && upperH.includes('3D CAD MODEL')) || SECTION_HEADERS.some(h => upperH.startsWith(h))) {
                closeUl();
                htmlParts.push(`<p><strong><u>${escapeHtml(cleanH)}</u></strong></p>`);
                return;
            }

            const mBul = line.match(/^(?:-\s+|\d+\.\s+)(.+)$/);
            if (mBul) {
                if (!inUl) {
                    htmlParts.push('<ul>');
                    inUl = true;
                }
                const itemTxt = mBul[1];
                let itemHtml = escapeHtml(itemTxt);
                if (itemTxt.includes('—')) {
                    const parts = itemTxt.split('—');
                    const p1 = escapeHtml(parts.shift().trim());
                    const p2 = escapeHtml(parts.join('—').trim());
                    itemHtml = `<strong>${p1}</strong> — ${p2}`;
                } else if (itemTxt.includes(':')) {
                    const parts = itemTxt.split(':');
                    const p1 = escapeHtml(parts.shift().trim());
                    const p2 = escapeHtml(parts.join(':').trim());
                    itemHtml = `<strong>${p1}:</strong> ${p2}`;
                }
                htmlParts.push(`<li>${itemHtml}</li>`);
                return;
            }

            closeUl();
            if (line.startsWith('Need an industrial') || line.endsWith('?')) {
                htmlParts.push(`<p><em><strong>${escapeHtml(line)}</strong></em></p>`);
            } else if (line.includes('WaterTreatment3D')) {
                const safeLine = escapeHtml(line).replace('WaterTreatment3D', '<strong>WaterTreatment3D</strong>');
                htmlParts.push(`<p><em>${safeLine}</em></p>`);
            } else {
                htmlParts.push(`<p>${escapeHtml(line)}</p>`);
            }
        });

        closeUl();
        return htmlParts.join('');
    }

    function isElementColoredNonNeutral(rootEl) {
        const nodes = [rootEl, ...Array.from(rootEl.querySelectorAll('*'))];
        for (const n of nodes) {
            if (n.nodeType !== Node.ELEMENT_NODE) continue;
            const inlineColor = (n.getAttribute('style') || '') + ' ' + (n.getAttribute('color') || '') + ' ' + (n.getAttribute('data-color') || '') + ' ' + (n.className || '');
            if (/color|red|yellow|green|amber|emerald|danger|warning|success/i.test(inlineColor)) {
                const cs = window.getComputedStyle(n).color || '';
                const m = cs.match(/(\d+)\s*,\s*(\d+)\s*,\s*(\d+)/);
                if (m) {
                    const r = parseInt(m[1]), g = parseInt(m[2]), b = parseInt(m[3]);
                    if (Math.max(r, g, b) - Math.min(r, g, b) > 30) return true;
                }
            }
            const cs = window.getComputedStyle(n).color || '';
            const m = cs.match(/(\d+)\s*,\s*(\d+)\s*,\s*(\d+)/);
            if (m) {
                const r = parseInt(m[1]), g = parseInt(m[2]), b = parseInt(m[3]);
                if (Math.max(r, g, b) - Math.min(r, g, b) > 35) return true;
            }
        }
        return false;
    }

    function findFabToolbarColorButton(descWrapper, descEl) {
        const scope = descWrapper || descEl?.parentElement?.parentElement;
        if (!scope) return null;
        const edRect = descEl.getBoundingClientRect();
        // Toolbar buttons must be inside descWrapper and located ABOVE or near the top of descEl
        const barBtns = Array.from(scope.querySelectorAll('button, [role="button"]')).filter(b => {
            if (b.id?.includes('wt3d') || b.closest?.('#wt3d-fab-floating-panel')) return false;
            if (descEl.contains(b)) return false;
            const r = b.getBoundingClientRect();
            return r.width >= 16 && r.width <= 60 && r.height >= 16 && r.height <= 60 && r.top <= edRect.top + 45 && r.bottom >= edRect.top - 70;
        });

        if (barBtns.length === 0) return null;

        // 1. Match by aria-label / title / data-testid
        const byAttr = barBtns.find(b => {
            const meta = ((b.getAttribute('aria-label') || '') + ' ' + (b.getAttribute('title') || '') + ' ' + (b.getAttribute('data-testid') || '')).toLowerCase();
            return meta.includes('color') || meta.includes('palette') || meta.includes('highlight');
        });
        if (byAttr) return byAttr;

        // 2. Match by SVG structure: palette icon has >= 3 circle/path elements or sits right between Underline (U) and Link
        const uIdx = barBtns.findIndex(b => {
            const meta = ((b.getAttribute('aria-label') || '') + ' ' + (b.getAttribute('title') || '') + ' ' + (b.textContent || '')).toLowerCase().trim();
            return meta.includes('underline') || meta === 'u';
        });
        if (uIdx !== -1 && barBtns[uIdx + 1]) {
            return barBtns[uIdx + 1];
        }

        const bySvgCircles = barBtns.find(b => b.querySelectorAll('circle').length >= 2);
        if (bySvgCircles) return bySvgCircles;

        return null;
    }

    function classifyColorSwatch(el) {
        const meta = ((el.getAttribute('aria-label') || '') + ' ' + (el.getAttribute('title') || '') + ' ' + (el.getAttribute('data-color') || '') + ' ' + (el.getAttribute('value') || '') + ' ' + (el.textContent || '')).toLowerCase();
        if (meta.includes('red') || meta.includes('danger') || meta.includes('error') || meta.includes('#ef4444') || meta.includes('#dc2626') || meta.includes('#ff')) {
            if (!meta.includes('green') && !meta.includes('yellow')) return 'red';
        }
        if (meta.includes('yellow') || meta.includes('amber') || meta.includes('orange') || meta.includes('warning') || meta.includes('#eab308') || meta.includes('#f59e0b')) {
            return 'yellow';
        }
        if (meta.includes('green') || meta.includes('emerald') || meta.includes('success') || meta.includes('#22c55e') || meta.includes('#10b981')) {
            return 'green';
        }

        // Check computed backgroundColor, color, borderColor, and SVG fill/stroke on el and its children
        const nodes = [el, ...Array.from(el.querySelectorAll('*'))];
        for (const n of nodes) {
            const cs = window.getComputedStyle(n);
            const candidates = [
                cs.backgroundColor,
                cs.color,
                cs.fill,
                n.getAttribute?.('fill'),
                n.getAttribute?.('stroke'),
                n.style?.backgroundColor,
                n.style?.color
            ].filter(Boolean);

            for (const cStr of candidates) {
                const rgb = String(cStr).match(/(\d+)\s*,\s*(\d+)\s*,\s*(\d+)/);
                if (rgb) {
                    const r = parseInt(rgb[1]), g = parseInt(rgb[2]), b = parseInt(rgb[3]);
                    if (Math.max(r, g, b) - Math.min(r, g, b) < 35) continue; // Skip white/gray/black
                    if (r > 150 && g < 115 && b < 115) return 'red';
                    if (r > 150 && g > 115 && b < 110) return 'yellow';
                    if (g > 125 && g > r + 20) return 'green';
                }
                const hex = String(cStr).trim().match(/^#([0-9a-f]{6})$/i);
                if (hex) {
                    const h = hex[1];
                    const r = parseInt(h.slice(0, 2), 16), g = parseInt(h.slice(2, 4), 16), b = parseInt(h.slice(4, 6), 16);
                    if (Math.max(r, g, b) - Math.min(r, g, b) < 35) continue;
                    if (r > 150 && g < 115 && b < 115) return 'red';
                    if (r > 150 && g > 115 && b < 110) return 'yellow';
                    if (g > 125 && g > r + 20) return 'green';
                }
            }
        }
        return null;
    }

    async function applyFabNativeToolbarColorsVerified(descEl, statusEl) {
        const HEADER_TARGETS = [
            { text: 'INDUSTRIAL WATER TREATMENT 3D CAD MODEL', colorType: 'green' },
            { text: 'SYSTEM OVERVIEW:', colorType: 'yellow' },
            { text: 'KEY FEATURES & TECHNICAL SPECIFICATIONS:', colorType: 'yellow' },
            { text: 'MAIN EQUIPMENT:', colorType: 'yellow' },
            { text: 'INCLUDED FILE FORMATS:', colorType: 'green' },
            { text: 'INCLUDED FORMATS IN PACKAGE:', colorType: 'green' },
            { text: 'SUITABLE FOR:', colorType: 'green' },
            { text: 'IDEAL USE CASES:', colorType: 'green' },
            { text: 'IMPORTANT INFORMATION:', colorType: 'red' }
        ];

        const descWrapper = findFabDescriptionWrapper();
        const colorBtn = findFabToolbarColorButton(descWrapper, descEl);
        if (!colorBtn) {
            console.warn('[WT3D Color] Không tìm thấy nút Color trên thanh công cụ Description');
            return { colored: 0, total: 0, reason: 'Không tìm thấy nút Color trên toolbar' };
        }

        // Find which headings exist in descEl
        const blocks = Array.from(descEl.querySelectorAll('p, h1, h2, h3, h4, div')).filter(node => {
            const t = (node.textContent || '').trim().toUpperCase();
            return HEADER_TARGETS.some(h => h.text === t);
        });

        const totalFound = blocks.length;
        if (totalFound === 0) {
            return { colored: 0, total: 0, reason: 'Không tìm thấy dòng tiêu đề trong Description' };
        }

        let coloredCount = 0;
        const btnRect = colorBtn.getBoundingClientRect();

        for (let i = 0; i < blocks.length; i++) {
            const el = blocks[i];
            const elTextUpper = (el.textContent || '').trim().toUpperCase();
            const targetCfg = HEADER_TARGETS.find(h => h.text === elTextUpper);
            if (!targetCfg) continue;

            if (isElementColoredNonNeutral(el)) {
                coloredCount++;
                continue;
            }

            if (statusEl) {
                statusEl.textContent = `🎨 Đang tô màu tiêu đề (${i + 1}/${totalFound}): ${targetCfg.text.substring(0, 22)}...`;
            }

            // 1. Select the exact text node(s) inside el using Range
            descEl.focus();
            const sel = window.getSelection();
            const range = document.createRange();
            const targetNode = el.querySelector('u, strong') || el;
            range.selectNodeContents(targetNode);
            sel.removeAllRanges();
            sel.addRange(range);
            await humanDelay(90, 150);

            // Verify selection still holds the exact heading text
            const selStr = (sel.toString() || '').trim().toUpperCase();
            if (selStr !== targetCfg.text) {
                console.warn(`[WT3D Color] Selection lệch ('${selStr}' !== '${targetCfg.text}'), dừng tô màu để bảo vệ form.`);
                break;
            }

            // 2. Open toolbar Color popover (dispatch mousedown with preventDefault-friendly events so editor keeps selection)
            await humanClick(colorBtn);
            await humanDelay(200, 320);

            // Re-assert selection if editor lost range when opening popover
            if ((window.getSelection()?.toString() || '').trim().toUpperCase() !== targetCfg.text) {
                try {
                    const r2 = document.createRange();
                    r2.selectNodeContents(targetNode);
                    window.getSelection().removeAllRanges();
                    window.getSelection().addRange(r2);
                } catch (_) {}
            }

            // 3. Scan only visible popover/menu elements near colorBtn (strictly outside #wt3d-fab-floating-panel)
            const candidates = Array.from(document.querySelectorAll('button, [role="button"], [role="option"], [role="menuitem"], li, span[tabindex], div[tabindex]')).filter(sw => {
                if (sw.id?.includes('wt3d') || sw.closest?.('#wt3d-fab-floating-panel')) return false;
                if (sw === colorBtn || descEl.contains(sw)) return false;
                const r = sw.getBoundingClientRect();
                if (r.width < 10 || r.width > 120 || r.height < 10 || r.height > 80) return false;
                // Must be near the toolbar colorBtn
                return Math.abs(r.top - btnRect.bottom) < 220 && Math.abs(r.left - btnRect.left) < 260;
            });

            const matchedSwatch = candidates.find(sw => classifyColorSwatch(sw) === targetCfg.colorType);
            if (!matchedSwatch) {
                console.warn(`[WT3D Color] Không tìm thấy ô màu '${targetCfg.colorType}' cho '${targetCfg.text}'. Đóng bảng màu & dừng.`);
                // Close popover cleanly if open
                document.body.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', code: 'Escape', keyCode: 27, bubbles: true }));
                break;
            }

            // The Color menu is a portal outside ProseMirror. Re-apply the DOM
            // range immediately before choosing its menu item; otherwise the
            // last heading (notably the red legal heading) can lose selection
            // while the popover receives focus.
            try {
                descEl.focus({ preventScroll: true });
                const r3 = document.createRange();
                r3.selectNodeContents(targetNode);
                const s3 = window.getSelection();
                s3.removeAllRanges();
                s3.addRange(r3);
                await humanDelay(40, 80);
                if ((s3.toString() || '').trim().toUpperCase() !== targetCfg.text) {
                    console.warn(`[WT3D Color] Selection lost before ${targetCfg.colorType} menu item; stopping safely.`);
                    break;
                }
            } catch (_) {
                console.warn(`[WT3D Color] Cannot restore selection before ${targetCfg.colorType} menu item; stopping safely.`);
                break;
            }

            await humanClick(matchedSwatch);
            await humanDelay(300, 480);

            // 4. Read back computed style / DOM attributes to verify the heading actually received color
            if (isElementColoredNonNeutral(el)) {
                coloredCount++;
                console.log(`[WT3D Color] ✅ Đã tô màu '${targetCfg.colorType}' thành công (${coloredCount}/${totalFound}): ${targetCfg.text}`);
            } else {
                console.warn(`[WT3D Color] ⚠️ Đã bấm swatch '${targetCfg.colorType}' nhưng readback chưa xác nhận đổi màu trên: ${targetCfg.text}`);
                break;
            }
        }

        window.getSelection()?.removeAllRanges();
        return { colored: coloredCount, total: totalFound };
    }

    async function injectFabRichDescription(descEl, rawDesc, statusEl = null) {
        if (!descEl) return { ok: false, colored: 0, total: 0 };
        descEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
        await humanDelay(150, 280);
        if (descEl.tagName === 'TEXTAREA') {
            setReactInputValue(descEl, rawDesc, { pressEnter: false });
            descEl.blur();
            const verified = (descEl.value || '').trim().length >= 40;
            return { ok: verified, colored: 0, total: 0 };
        }

        const richHtml = formatFabRichDescriptionHTML(rawDesc);
        descEl.focus();
        document.execCommand('selectAll', false, null);
        const inserted = document.execCommand('insertHTML', false, richHtml);
        if (!inserted || (descEl.innerText || '').trim().length < 25) {
            document.execCommand('selectAll', false, null);
            document.execCommand('insertText', false, rawDesc);
        }
        descEl.dispatchEvent(new InputEvent('input', { bubbles: true, inputType: 'insertFromPaste' }));
        descEl.dispatchEvent(new Event('change', { bubbles: true }));
        await humanDelay(200, 320);

        // Apply verified native toolbar 3-color pass
        const colorRes = await applyFabNativeToolbarColorsVerified(descEl, statusEl);

        // Blur and read back state to verify persistence
        window.getSelection()?.removeAllRanges();
        descEl.dispatchEvent(new Event('input', { bubbles: true }));
        descEl.dispatchEvent(new Event('change', { bubbles: true }));
        descEl.blur();
        await humanDelay(200, 300);

        const persistedText = (descEl.innerText || descEl.textContent || '').trim();
        const isPersisted = persistedText.length >= 40 && persistedText.includes('WaterTreatment3D');
        return {
            ok: isPersisted,
            colored: colorRes.colored,
            total: colorRes.total,
            reason: colorRes.reason
        };
    }

    async function selectFabCategory(category, forceOverwrite = false) {
        const targetCategory = category || 'Environments / Industrial';
        const targetLower = targetCategory.toLowerCase().trim();
        console.log('[WT3D] >>> selectFabCategory:', targetCategory, 'forceOverwrite:', forceOverwrite);
        try {
            let catWrapper = null;
            const allLabels = Array.from(document.querySelectorAll('label, div, span, p, h3, h4'));
            for (const el of allLabels) {
                if (el.id?.includes('wt3d') || el.closest?.('#wt3d-fab-floating-panel')) continue;
                if (el.closest?.('[role="dialog"], [class*="modal" i]')) continue;
                const t = (el.textContent || '').trim();
                if (t === 'Category *' || t === 'Category') {
                    let p = el.parentElement;
                    for (let i = 0; i < 4 && p; i++) {
                        const fullTxt = (p.textContent || '');
                        if (fullTxt.includes('Title *') || fullTxt.includes('Tags *') || fullTxt.includes('Description *')) {
                            break;
                        }
                        if (p.querySelector('button, [role="combobox"], [role="button"], input, div[tabindex="0"]')) {
                            catWrapper = p;
                            break;
                        }
                        p = p.parentElement;
                    }
                    if (catWrapper) break;
                }
            }

            const readCategoryFieldText = () => {
                if (!catWrapper) return '';
                const inp = catWrapper.querySelector('input:not([type="hidden"])');
                const inpVal = inp ? (inp.value || '').trim() : '';
                const wrapTxt = (catWrapper.textContent || '').replace(/\s+/g, ' ').trim();
                return (inpVal + ' ' + wrapTxt).toLowerCase();
            };

            if (!forceOverwrite && catWrapper) {
                const curTxt = readCategoryFieldText();
                if (curTxt.includes(targetLower)) {
                    console.log('[WT3D] Category already verified as:', targetCategory);
                    return true;
                }
            }

            let catTrigger = catWrapper
                ? catWrapper.querySelector('input:not([type="hidden"]), [role="combobox"], button, [role="button"], div[tabindex="0"]')
                : null;

            if (!catTrigger) {
                console.log('[WT3D] Category trigger NOT found inside isolated Category wrapper');
                return false;
            }

            catTrigger.scrollIntoView({ behavior: 'smooth', block: 'center' });
            await humanDelay(200, 350);
            await humanClick(catTrigger);
            await humanDelay(400, 650);

            let searchInput = null;
            if (catTrigger.tagName === 'INPUT') {
                searchInput = catTrigger;
            } else if (catWrapper) {
                searchInput = catWrapper.querySelector('input:not([type="hidden"])');
            }
            if (!searchInput) {
                searchInput = Array.from(document.querySelectorAll('[role="listbox"] input, [role="dialog"] input, [data-radix-popper-content-wrapper] input')).find(inp => {
                    if (inp.id?.includes('wt3d') || inp.closest?.('#wt3d-fab-floating-panel')) return false;
                    const ph = (inp.placeholder || '').toLowerCase();
                    const aria = (inp.getAttribute('aria-label') || '').toLowerCase();
                    if (ph.includes('title') || ph.includes('tag') || aria.includes('title') || aria.includes('tag')) return false;
                    return inp.getBoundingClientRect().width > 40;
                });
            }

            const searchKeyword = targetLower.includes('industrial') && targetLower.includes('environment')
                ? 'Industrial'
                : 'Tools, Objects';

            if (searchInput) {
                const ph = (searchInput.placeholder || '').toLowerCase();
                if (!ph.includes('title') && !ph.includes('tag') && searchInput.maxLength !== 80) {
                    console.log('[WT3D] Typing Category search keyword into isolated Category input:', searchKeyword);
                    searchInput.focus();
                    setReactInputValue(searchInput, searchKeyword, { pressEnter: false });
                    await humanDelay(400, 650);
                }
            }

            const scanStart = Date.now();
            let matched = null;

            while (Date.now() - scanStart < 3800 && !matched) {
                const candidates = Array.from(document.querySelectorAll('[role="option"], [role="menuitem"], li, button, div, span')).filter(el => {
                    if (el.id?.includes('wt3d') || el.closest?.('#wt3d-fab-floating-panel')) return false;
                    if (el === catTrigger || el === searchInput || el.tagName === 'INPUT') return false;
                    if (catWrapper && catWrapper.contains(el) && el.querySelector('input, button')) return false;
                    const rect = el.getBoundingClientRect();
                    if (rect.width === 0 || rect.height === 0 || rect.height > 80) return false;
                    const t = (el.textContent || '').trim().toLowerCase().replace(/\s+/g, ' ');
                    if (!t) return false;
                    if (t === targetLower) return true;
                    if (targetLower.includes('environments') && (t === 'environments / industrial' || (t.includes('environments') && t.includes('industrial') && t.length < 40))) return true;
                    if (targetLower.includes('tools, objects') && t.startsWith('tools, objects & decor') && t.length < 50) return true;
                    return false;
                });

                if (candidates.length > 0) {
                    matched = candidates.reduce((a, b) => (a.textContent || '').trim().length <= (b.textContent || '').trim().length ? a : b);
                } else {
                    await sleep(100);
                }
            }

            if (!matched) {
                console.log('[WT3D] Category option NOT found after 3.8s for:', targetCategory);
                return false;
            }

            console.log('[WT3D] Category option matched & clicking:', matched.textContent.trim());
            matched.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
            await humanDelay(180, 300);
            await humanClick(matched);
            await humanDelay(400, 600);

            // [FIX 3] Read-back verification: confirm the field now displays targetCategory!
            const afterTxt = readCategoryFieldText();
            const isVerified = afterTxt.includes(targetLower) ||
                (targetLower.includes('environments') && afterTxt.includes('environments') && afterTxt.includes('industrial')) ||
                (targetLower.includes('tools, objects') && afterTxt.includes('tools, objects'));

            console.log('[WT3D] Category read-back verification:', isVerified, 'field text:', afterTxt.substring(0, 80));
            return isVerified;
        } catch (e) {
            console.log('[WT3D] Category error:', e.message);
            return false;
        }
    }

    // =====================================================================
    // =====================================================================

    // 3. TẠO FLOATING PANEL GIAO DIỆN

    // =====================================================================

