                    <span id="wt3d-close-btn" style="cursor: pointer; color: #94a3b8; font-weight: bold; font-size: 20px; width: 28px; height: 28px; display: flex; align-items: center; justify-content: center; border-radius: 6px; background: #1e293b; transition: all 0.2s;" title="Đóng bảng">✕</span>
